1|CHANGE g0035 REMOVED part 1/1 encoding=literal
2|#if !defined(MBEDTLS_ECP_NO_INTERNAL_RNG)
3|/*
4| * Currently ecp_mul() takes a RNG function as an argument, used for
5| * side-channel protection, but it can be NULL. The initial reasoning was
6| * that people will pass non-NULL RNG when they care about side-channels, but
7| * unfortunately we have some APIs that call ecp_mul() with a NULL RNG, with
8| * no opportunity for the user to do anything about it.
9| *
10| * The obvious strategies for addressing that include:
11| * - change those APIs so that they take RNG arguments;
12| * - require a global RNG to be available to all crypto modules.
13| *
14| * Unfortunately those would break compatibility. So what we do instead is
15| * have our own internal DRBG instance, seeded from the secret scalar.
16| *
17| * The following is a light-weight abstraction layer for doing that with
18| * HMAC_DRBG (first choice) or CTR_DRBG.
19| */
20|
21|#if defined(MBEDTLS_HMAC_DRBG_C)
22|
23|/* DRBG context type */
24|typedef mbedtls_hmac_drbg_context ecp_drbg_context;
25|
26|/* DRBG context init */
27|static inline void ecp_drbg_init( ecp_drbg_context *ctx )
28|{
29|    mbedtls_hmac_drbg_init( ctx );
30|}
31|
32|/* DRBG context free */
33|static inline void ecp_drbg_free( ecp_drbg_context *ctx )
34|{
35|    mbedtls_hmac_drbg_free( ctx );
36|}
37|
38|/* DRBG function */
39|static inline int ecp_drbg_random( void *p_rng,
40|                                   unsigned char *output, size_t output_len )
41|{
42|    return( mbedtls_hmac_drbg_random( p_rng, output, output_len ) );
43|}
44|
45|/* DRBG context seeding */
46|static int ecp_drbg_seed( ecp_drbg_context *ctx,
47|                   const mbedtls_mpi *secret, size_t secret_len )
48|{
49|    int ret;
50|    unsigned char secret_bytes[MBEDTLS_ECP_MAX_BYTES];
51|    /* The list starts with strong hashes */
52|    const mbedtls_md_type_t md_type = mbedtls_md_list()[0];
53|    const mbedtls_md_info_t *md_info = mbedtls_md_info_from_type( md_type );
54|
55|    if( secret_len > MBEDTLS_ECP_MAX_BYTES )
56|    {
57|        ret = MBEDTLS_ERR_ECP_RANDOM_FAILED;
58|        goto cleanup;
59|    }
60|
61|    MBEDTLS_MPI_CHK( mbedtls_mpi_write_binary( secret,
62|                                               secret_bytes, secret_len ) );
63|
64|    ret = mbedtls_hmac_drbg_seed_buf( ctx, md_info, secret_bytes, secret_len );
65|
66|cleanup:
67|    mbedtls_platform_zeroize( secret_bytes, secret_len );
68|
69|    return( ret );
70|}
71|
72|#elif defined(MBEDTLS_CTR_DRBG_C)
73|
74|/* DRBG context type */
75|typedef mbedtls_ctr_drbg_context ecp_drbg_context;
76|
77|/* DRBG context init */
78|static inline void ecp_drbg_init( ecp_drbg_context *ctx )
79|{
80|    mbedtls_ctr_drbg_init( ctx );
81|}
82|
83|/* DRBG context free */
84|static inline void ecp_drbg_free( ecp_drbg_context *ctx )
85|{
86|    mbedtls_ctr_drbg_free( ctx );
87|}
88|
89|/* DRBG function */
90|static inline int ecp_drbg_random( void *p_rng,
91|                                   unsigned char *output, size_t output_len )
92|{
93|    return( mbedtls_ctr_drbg_random( p_rng, output, output_len ) );
94|}
95|
96|/*
97| * Since CTR_DRBG doesn't have a seed_buf() function the way HMAC_DRBG does,
98| * we need to pass an entropy function when seeding. So we use a dummy
99| * function for that, and pass the actual entropy as customisation string.
100| * (During seeding of CTR_DRBG the entropy input and customisation string are
101| * concatenated before being used to update the secret state.)
102| */
103|static int ecp_ctr_drbg_null_entropy(void *ctx, unsigned char *out, size_t len)
104|{
105|    (void) ctx;
106|    memset( out, 0, len );
107|    return( 0 );
108|}
109|
110|/* DRBG context seeding */
111|static int ecp_drbg_seed( ecp_drbg_context *ctx,
112|                   const mbedtls_mpi *secret, size_t secret_len )
113|{
114|    int ret;
115|    unsigned char secret_bytes[MBEDTLS_ECP_MAX_BYTES];
116|
117|    if( secret_len > MBEDTLS_ECP_MAX_BYTES )
118|    {
119|        ret = MBEDTLS_ERR_ECP_RANDOM_FAILED;
120|        goto cleanup;
121|    }
122|
123|    MBEDTLS_MPI_CHK( mbedtls_mpi_write_binary( secret,
124|                                               secret_bytes, secret_len ) );
125|
126|    ret = mbedtls_ctr_drbg_seed( ctx, ecp_ctr_drbg_null_entropy, NULL,
127|                                 secret_bytes, secret_len );
128|
129|cleanup:
130|    mbedtls_platform_zeroize( secret_bytes, secret_len );
131|
132|    return( ret );
133|}
134|
135|#else
136|#error "Invalid configuration detected. Include check_config.h to ensure that the configuration is valid."
137|#endif /* DRBG modules */
138|#endif /* MBEDTLS_ECP_NO_INTERNAL_RNG */

