1953|static int ecp_comb_recode_scalar( const mbedtls_ecp_group *grp,
1954|                                   const mbedtls_mpi *m,
1955|                                   unsigned char k[COMB_MAX_D + 1],
1956|                                   size_t d,
1957|                                   unsigned char w,
1958|                                   unsigned char *parity_trick )
