3069|int mbedtls_ecp_check_pub_priv(
3070|        const mbedtls_ecp_keypair *pub, const mbedtls_ecp_keypair *prv,
3071|        int (*f_rng)(void *, unsigned char *, size_t), void *p_rng )
3072|{
