3079|    if( pub->grp.id == MBEDTLS_ECP_DP_NONE ||
3080|        pub->grp.id != prv->grp.id ||
3081|        mbedtls_mpi_cmp_mpi( &pub->Q.X, &prv->Q.X ) ||
3082|        mbedtls_mpi_cmp_mpi( &pub->Q.Y, &prv->Q.Y ) ||
3083|        mbedtls_mpi_cmp_mpi( &pub->Q.Z, &prv->Q.Z ) )
3084|    {
3085|        return( MBEDTLS_ERR_ECP_BAD_INPUT_DATA );
3086|    }
3087|
3088|    mbedtls_ecp_point_init( &Q );
3089|    mbedtls_ecp_group_init( &grp );
3090|
3091|    /* mbedtls_ecp_mul() needs a non-const group... */
3092|    mbedtls_ecp_group_copy( &grp, &prv->grp );
3093|
3094|    /* Also checks d is valid */
3095|    MBEDTLS_MPI_CHK( mbedtls_ecp_mul( &grp, &Q, &prv->d, &prv->grp.G, f_rng, p_rng ) );
3096|
3097|    if( mbedtls_mpi_cmp_mpi( &Q.X, &prv->Q.X ) ||
3098|        mbedtls_mpi_cmp_mpi( &Q.Y, &prv->Q.Y ) ||
3099|        mbedtls_mpi_cmp_mpi( &Q.Z, &prv->Q.Z ) )
3100|    {
3101|        ret = MBEDTLS_ERR_ECP_BAD_INPUT_DATA;
3102|        goto cleanup;
3103|    }
3104|
3105|cleanup:
3106|    mbedtls_ecp_point_free( &Q );
3107|    mbedtls_ecp_group_free( &grp );
3108|
3109|    return( ret );
3110|}

