3325|        mbedtls_printf( "Unexpected error, return code = %08X\n", (unsigned int) ret );
3326|
3327|    mbedtls_ecp_group_free( &grp );
3328|    mbedtls_ecp_point_free( &R );
3329|    mbedtls_ecp_point_free( &P );
3330|    mbedtls_mpi_free( &m );
