874|    /*
875|     * RFC 5915, or SEC1 Appendix C.4
876|     *
877|     * ECPrivateKey ::= SEQUENCE {
878|     *      version        INTEGER { ecPrivkeyVer1(1) } (ecPrivkeyVer1),
879|     *      privateKey     OCTET STRING,
