923|            }
924|        }
925|        else if( ret != MBEDTLS_ERR_ASN1_UNEXPECTED_TAG )
926|        {
927|            mbedtls_ecp_keypair_free( eck );
928|            return( MBEDTLS_ERROR_ADD( MBEDTLS_ERR_PK_KEY_INVALID_FORMAT, ret ) );
929|        }
930|    }
