139|
140|    /* Copy out the pointer to the RSA context, and reset the PK context
141|     * such that pk_free doesn't free the RSA context we just grabbed. */
142|    *p_rsa = mbedtls_pk_rsa( ctx );
143|    ctx.pk_info = NULL;
