1142|            goto exit;
1143|        if( ( ret = mbedtls_md_update( md_ctx, counter, 4 ) ) != 0 )
1144|            goto exit;
1145|        if( ( ret = mbedtls_md_finish( md_ctx, mask ) ) != 0 )
1146|            goto exit;
