693|sni_entry *sni_parse( char *sni_string )
694|{
695|    sni_entry *cur = NULL, *new = NULL;
696|    char *p = sni_string;
697|    char *end = p;
698|    char *crt_file, *key_file, *ca_file, *auth_str;
699|#if defined(MBEDTLS_X509_CRL_PARSE_C)
700|    char *crl_file;
701|#endif
702|
703|    while( *end != '\0' )
704|        ++end;
705|    *end = ',';
706|
707|    while( p <= end )
708|    {
709|        if( ( new = mbedtls_calloc( 1, sizeof( sni_entry ) ) ) == NULL )
710|        {
711|            sni_free( cur );
712|            return( NULL );
713|        }
714|
715|        GET_ITEM( new->name );
716|        GET_ITEM( crt_file );
717|        GET_ITEM( key_file );
718|        GET_ITEM( ca_file );
719|#if defined(MBEDTLS_X509_CRL_PARSE_C)
720|        GET_ITEM( crl_file );
721|#endif
722|        GET_ITEM( auth_str );
723|
724|        if( ( new->cert = mbedtls_calloc( 1, sizeof( mbedtls_x509_crt ) ) ) == NULL ||
725|            ( new->key = mbedtls_calloc( 1, sizeof( mbedtls_pk_context ) ) ) == NULL )
726|            goto error;
727|
728|        mbedtls_x509_crt_init( new->cert );
729|        mbedtls_pk_init( new->key );
730|
731|        if( mbedtls_x509_crt_parse_file( new->cert, crt_file ) != 0 ||
732|            mbedtls_pk_parse_keyfile( new->key, key_file, "", rng_get, &rng ) != 0 )
733|            goto error;
734|
735|        if( strcmp( ca_file, "-" ) != 0 )
736|        {
737|            if( ( new->ca = mbedtls_calloc( 1, sizeof( mbedtls_x509_crt ) ) ) == NULL )
738|                goto error;
739|
740|            mbedtls_x509_crt_init( new->ca );
741|
742|            if( mbedtls_x509_crt_parse_file( new->ca, ca_file ) != 0 )
743|                goto error;
744|        }
745|
746|#if defined(MBEDTLS_X509_CRL_PARSE_C)
747|        if( strcmp( crl_file, "-" ) != 0 )
748|        {
749|            if( ( new->crl = mbedtls_calloc( 1, sizeof( mbedtls_x509_crl ) ) ) == NULL )
750|                goto error;
751|
752|            mbedtls_x509_crl_init( new->crl );
753|
754|            if( mbedtls_x509_crl_parse_file( new->crl, crl_file ) != 0 )
755|                goto error;
756|        }
757|#endif
758|
759|        if( strcmp( auth_str, "-" ) != 0 )
760|        {
761|            if( ( new->authmode = get_auth_mode( auth_str ) ) < 0 )
762|                goto error;
763|        }
764|        else
765|            new->authmode = DFL_AUTH_MODE;
766|
767|        new->next = cur;
768|        cur = new;
769|    }
770|
771|    return( cur );
772|
773|error:
774|    sni_free( new );
775|    sni_free( cur );
776|    return( NULL );
